CREATE TABLE public.order_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),seq bigint GENERATED ALWAYS AS IDENTITY UNIQUE,order_id uuid NOT NULL REFERENCES public.orders(id),customer_id uuid NOT NULL REFERENCES public.profiles(id),rider_id uuid NOT NULL REFERENCES public.profiles(id),sender_id uuid NOT NULL REFERENCES public.profiles(id),text text NOT NULL CHECK(length(text) BETWEEN 1 AND 2000),idempotency_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(sender_id,idempotency_key),CHECK(sender_id IN(customer_id,rider_id)));
CREATE INDEX chat_order_idx ON public.order_messages(order_id,seq);
CREATE TABLE vendo_internal.reassignment_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES public.orders(id),actor_id uuid NOT NULL REFERENCES public.profiles(id),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE vendo_internal.chat_reads(order_id uuid NOT NULL REFERENCES public.orders(id),profile_id uuid NOT NULL REFERENCES public.profiles(id),last_read_seq bigint NOT NULL CHECK(last_read_seq>=0),PRIMARY KEY(order_id,profile_id));
CREATE TABLE vendo_internal.rider_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),rider_id uuid NOT NULL REFERENCES vendo_internal.riders(profile_id),kind text NOT NULL CHECK(kind IN('identity','license','vehicle','insurance')),mime text NOT NULL CHECK(mime IN('image/jpeg','image/png','application/pdf')),encrypted text NOT NULL,sha256 text NOT NULL,bytes integer NOT NULL CHECK(bytes BETWEEN 1 AND 2097152),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected')),review_note text,created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz,reviewed_by uuid REFERENCES public.profiles(id),UNIQUE(rider_id,kind));
CREATE TABLE vendo_internal.membership_tiers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,active boolean NOT NULL,placement_rank integer NOT NULL CHECK(placement_rank BETWEEN 0 AND 100),commission_bps integer CHECK(commission_bps BETWEEN 0 AND 10000));
CREATE TABLE vendo_internal.vendor_memberships(vendor_id uuid PRIMARY KEY REFERENCES public.vendors(id),tier_id uuid NOT NULL REFERENCES vendo_internal.membership_tiers(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL CHECK(ends_at>starts_at));
CREATE TABLE public.promo_banners(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),city_id uuid REFERENCES public.cities(id),title text NOT NULL,body text NOT NULL,image_url text,action text NOT NULL CHECK(action IN('food','dispatch','wallet','vendor')),vendor_id uuid REFERENCES public.vendors(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL CHECK(ends_at>starts_at),active boolean NOT NULL,priority integer NOT NULL CHECK(priority BETWEEN 0 AND 100),CHECK((action='vendor')=(vendor_id IS NOT NULL)));
ALTER TABLE public.cities ADD COLUMN surge_bps integer NOT NULL DEFAULT 10000 CHECK(surge_bps BETWEEN 10000 AND 50000);
CREATE TABLE vendo_internal.finance_policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),city_id uuid NOT NULL REFERENCES public.cities(id),enabled boolean NOT NULL,config jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE vendo_internal.order_finance_terms(order_id uuid PRIMARY KEY REFERENCES public.orders(id),policy_id uuid REFERENCES vendo_internal.finance_policies(id),terms jsonb);
CREATE FUNCTION vendo_internal.snapshot_finance_terms() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE p vendo_internal.finance_policies; commission integer;
BEGIN
 SELECT * INTO p FROM vendo_internal.finance_policies WHERE city_id=(NEW.quote->>'city_id')::uuid ORDER BY created_at DESC,id DESC LIMIT 1;
 IF p.enabled THEN
 SELECT t.commission_bps INTO commission FROM vendo_internal.vendor_memberships m JOIN vendo_internal.membership_tiers t ON t.id=m.tier_id WHERE m.vendor_id=NEW.vendor_id AND m.starts_at<=now() AND m.ends_at>now() AND t.active;
 INSERT INTO vendo_internal.order_finance_terms(order_id,policy_id,terms) VALUES(NEW.id,p.id,CASE WHEN commission IS NULL THEN p.config ELSE jsonb_set(p.config,'{vendor_commission_bps}',to_jsonb(commission)) END);
 ELSE INSERT INTO vendo_internal.order_finance_terms(order_id) VALUES(NEW.id);END IF;RETURN NEW;
END; $$;
CREATE TRIGGER finance_terms_created AFTER INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION vendo_internal.snapshot_finance_terms();
CREATE TABLE vendo_internal.earnings_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN('rider','vendor')),entity_id uuid NOT NULL,available_kobo bigint NOT NULL DEFAULT 0 CHECK(available_kobo BETWEEN 0 AND 9000000000000),held_kobo bigint NOT NULL DEFAULT 0 CHECK(held_kobo BETWEEN 0 AND 9000000000000),UNIQUE(kind,entity_id));
CREATE TABLE vendo_internal.settlements(order_id uuid PRIMARY KEY REFERENCES public.orders(id),rider_id uuid NOT NULL REFERENCES public.profiles(id),vendor_id uuid REFERENCES public.vendors(id),rider_kobo bigint NOT NULL CHECK(rider_kobo>=0),vendor_kobo bigint NOT NULL CHECK(vendor_kobo>=0),platform_kobo bigint NOT NULL,paid_kobo bigint NOT NULL CHECK(paid_kobo>0),created_at timestamptz NOT NULL DEFAULT now(),CHECK(rider_kobo+vendor_kobo+platform_kobo=paid_kobo));
CREATE TABLE vendo_internal.payout_banks(account_id uuid PRIMARY KEY REFERENCES vendo_internal.earnings_accounts(id),bank_code text NOT NULL,last_four text NOT NULL,account_name text NOT NULL,recipient_code text NOT NULL,bank_hash text NOT NULL UNIQUE,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE vendo_internal.withdrawals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES vendo_internal.earnings_accounts(id),requested_by uuid NOT NULL REFERENCES public.profiles(id),reference text NOT NULL UNIQUE,idempotency_key text NOT NULL,amount_kobo bigint NOT NULL CHECK(amount_kobo BETWEEN 1 AND 1000000000),recipient_code text NOT NULL,status text NOT NULL DEFAULT 'requested' CHECK(status IN('requested','approved','rejected','submitting','pending','succeeded','failed','review','reversed')),provider_code text UNIQUE,review_note text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),last_checked_at timestamptz,UNIQUE(account_id,idempotency_key));
CREATE TABLE vendo_internal.earnings_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES vendo_internal.earnings_accounts(id),reference text NOT NULL UNIQUE,kind text NOT NULL CHECK(kind IN('earning','hold','release','payout','reversal')),available_delta bigint NOT NULL,held_delta bigint NOT NULL,available_after bigint NOT NULL CHECK(available_after>=0),held_after bigint NOT NULL CHECK(held_after>=0),order_id uuid REFERENCES public.orders(id),withdrawal_id uuid REFERENCES vendo_internal.withdrawals(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE vendo_internal.transfer_events(digest text PRIMARY KEY,reference text NOT NULL,event text NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz);
CREATE TABLE vendo_internal.worker_runs(kind text PRIMARY KEY,last_success_at timestamptz,last_failure_at timestamptz,last_duration_ms integer NOT NULL DEFAULT 0);
CREATE INDEX operational_orders_city_idx ON public.orders((quote->>'city_id'),created_at DESC,id);
CREATE INDEX pending_withdrawals_idx ON vendo_internal.withdrawals(last_checked_at,created_at) WHERE status IN('approved','submitting','pending','review','succeeded');
CREATE FUNCTION vendo_internal.immutable_earnings() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN RAISE EXCEPTION 'Earnings ledger entries are immutable';END;$$;
CREATE TRIGGER immutable_earnings BEFORE UPDATE OR DELETE ON vendo_internal.earnings_ledger FOR EACH ROW EXECUTE FUNCTION vendo_internal.immutable_earnings();
CREATE TRIGGER immutable_settlements BEFORE UPDATE OR DELETE ON vendo_internal.settlements FOR EACH ROW EXECUTE FUNCTION vendo_internal.immutable_earnings();
ALTER TABLE public.order_messages ENABLE ROW LEVEL SECURITY;ALTER TABLE public.promo_banners ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.order_messages,public.promo_banners FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.order_messages TO authenticated;GRANT SELECT ON public.promo_banners TO anon,authenticated;
GRANT ALL ON public.order_messages,public.promo_banners TO service_role;GRANT USAGE,SELECT ON SEQUENCE public.order_messages_seq_seq TO service_role;
CREATE POLICY chat_participants ON public.order_messages FOR SELECT TO authenticated USING((customer_id=(SELECT auth.uid()) OR rider_id=(SELECT auth.uid())) AND EXISTS(SELECT 1 FROM public.profiles WHERE id=(SELECT auth.uid()) AND status='active' AND (id=customer_id OR role='rider')));
CREATE POLICY banners_active ON public.promo_banners FOR SELECT TO anon,authenticated USING(active AND starts_at<=now() AND ends_at>now() AND (city_id IS NULL OR EXISTS(SELECT 1 FROM public.cities WHERE id=city_id AND is_active)) AND (vendor_id IS NULL OR EXISTS(SELECT 1 FROM public.vendors WHERE id=vendor_id AND is_active)));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['reassignment_notes','chat_reads','rider_documents','membership_tiers','vendor_memberships','finance_policies','order_finance_terms','earnings_accounts','settlements','payout_banks','withdrawals','earnings_ledger','transfer_events','worker_runs'] LOOP EXECUTE format('ALTER TABLE vendo_internal.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON vendo_internal.%I FROM PUBLIC,anon,authenticated',t);EXECUTE format('GRANT ALL ON vendo_internal.%I TO service_role',t);END LOOP;END;$$;
REVOKE ALL ON FUNCTION vendo_internal.snapshot_finance_terms(),vendo_internal.immutable_earnings() FROM PUBLIC,anon,authenticated;
